[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$ReceiptPath)
$ErrorActionPreference='Stop';$issues=[Collections.Generic.List[string]]::new();$r=Get-Content -Raw -Encoding UTF8 -LiteralPath $ReceiptPath|ConvertFrom-Json
if($r.schemaVersion -ne 1){$issues.Add('SCHEMA_VERSION')};if($r.recordType -ne 'WebPageStudioBackendRuntimeReceipt'){$issues.Add('RECORD_TYPE')};foreach($n in 'receiptId','contractId','status','method','targetHost','allowlist','timeoutSeconds','retry','recovery','runtimeStatus','nonClaims'){if($null -eq $r.PSObject.Properties[$n]){$issues.Add("MISSING_$n")}}
if($r.method -notin @('GET','HEAD')){$issues.Add('METHOD_NOT_READ_ONLY')};if($r.allowlist.decision -eq 'allowed' -and [string]$r.allowlist.matchedHost -ne [string]$r.targetHost){$issues.Add('ALLOWLIST_MATCH_MISMATCH')};$localFixture=([string]$r.targetHost -eq 'local-fixture' -and [int]$r.networkCalls -eq 0 -and $r.allowlist.decision -eq 'not-evaluated');if($r.status -in @('passed','timeout','cancelled') -and $r.allowlist.decision -ne 'allowed' -and -not $localFixture){$issues.Add('ALLOWLIST_NOT_ACCEPTED')};if($r.retry.maxAttempts -lt $r.attempts){$issues.Add('RETRY_ATTEMPTS_EXCEEDED')};if(-not $r.redaction.applied -or $r.redaction.responseBodyPersisted -or $r.redaction.sensitiveHeadersPersisted){$issues.Add('REDACTION_POLICY')};if($r.networkCalls -gt $r.attempts){$issues.Add('NETWORK_CALL_COUNT')};if($r.status -eq 'cancelled' -and -not $r.cancellation.observed){$issues.Add('CANCEL_NOT_OBSERVED')};if($r.status -eq 'timeout' -and $r.runtimeStatus -ne 'runtime-timeout'){$issues.Add('TIMEOUT_STATUS')};if($r.status -eq 'not-run' -and $r.runtimeStatus -ne 'runtime-not-run'){$issues.Add('NOT_RUN_STATUS')};if($r.status -eq 'failed' -and $r.recovery.outcome -notin @('recovered','failed','not-run')){$issues.Add('RECOVERY_OUTCOME_INVALID')}
$o=[ordered]@{validator='network-runtime-receipt';status=if($issues.Count){'blocked'}else{'passed'};findingCount=$issues.Count;findings=@($issues);runtimeStatus=[string]$r.runtimeStatus;nonClaims=@('does-not-prove-production-availability','does-not-persist-response-body')};$o|ConvertTo-Json -Depth 8;if($issues.Count){exit 1}
